+function toggleVehicle(){if(driving){driving=false;avatar.visible=true;avatar.position.copy(car.position);avatar.position.x+=2;walkYaw=yaw;velocity*=.4;toast('Zu Fuß — kehre zu deinem Wagen zurück');}else if(avatar.position.distanceTo(car.position)<5){driving=true;avatar.visible=false;toast('Fahrzeug betreten');}else toast('Nähere dich deinem Wagen');document.querySelector('[data-control="exit"]').textContent=driving?'EXIT':'ENTER';}
 function onAction(){if(!driving){toggleVehicle();return}toast('Checkpoint-Ziel: Fahre durch den leuchtenden Ring');}
 document.querySelector('#play').addEventListener('click',()=>{started=true;document.querySelector('#start').classList.add('hidden');toast('Auftrag gestartet — los geht’s!')});
 document.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyE'&&!keys._e){toggleVehicle();keys._e=true}if(e.code==='KeyF')onAction()});document.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyE')keys._e=false});
 function updateInputs(){input.gas=Math.max(+(keys.KeyW||keys.ArrowUp),touchInput.gas);input.brake=Math.max(+(keys.KeyS||keys.ArrowDown),touchInput.brake);input.steer=THREE.MathUtils.clamp((+(keys.KeyD||keys.ArrowRight))-(+(keys.KeyA||keys.ArrowLeft))+touchInput.steer,-1,1);input.sprint=!!keys.ShiftLeft;}
